async function applyBulkOperations(operations:BulkOperation[]){const current=project();if(!current||operations.length===0)return false;const slugs=new Set(operations.map(item=>item.slug)),before=tickets.value.filter(ticket=>slugs.has(ticket.slug)),selectedBefore=selectedTicket.value;tickets.value=tickets.value.map(ticket=>{const operation=operations.find(item=>item.slug===ticket.slug);return operation?projectTicketPatch(ticket,operation.patch):ticket});if(selectedTicket.value){const operation=operations.find(item=>item.slug===selectedTicket.value?.slug);if(operation)selectedTicket.value=projectTicketPatch(selectedTicket.value,operation.patch)}try{const updated=await new Api(current.apiPath).batchUpdateCheckoutTickets(current.id,operations.map(operation=>{const ticket=before.find(item=>item.slug===operation.slug),token=selectedBefore?.slug===operation.slug?selectedBefore.concurrency_token:ticket?.updated_at;return{id:operation.id,patch:token?{...operation.patch,expected_token:token}:operation.patch}}));if(project()?.id!==current.id)return false;tickets.value=tickets.value.map(ticket=>{const match=updated.find(item=>item.id===ticket.id);return match?ticketRowFromFull(ticket,match):ticket});const selectedUpdate=selectedTicket.value&&updated.find(item=>item.id===selectedTicket.value?.id);if(selectedUpdate)selectedTicket.value=selectedUpdate;error.value='';return true}catch(reason){tickets.value=tickets.value.map(ticket=>before.find(item=>item.slug===ticket.slug)??ticket);if(selectedBefore&&slugs.has(selectedBefore.slug))selectedTicket.value=selectedBefore;error.value=reason instanceof Error?reason.message:String(reason);return false}}
