function clipboardTicket(ticket:FullTicket|WireTicketRow,loaded?:FullTicket):ClipboardTicket {const full='details' in ticket?ticket:loaded;return{id:ticket.id,slug:ticket.slug,connection_id:ticket.connection_id,native_id:ticket.native_id,title:ticket.title,details:full?.details??'',category:ticket.category??'issue',priority:ticket.priority,status:ticket.status,up_next:ticket.up_next,tags:ticket.tags,notes:full?.notes.map(note=>({kind:note.kind,text:note.text}))??[],attachments:full?.attachments.map(item=>({id:item.id,filename:item.filename}))??[]}}
