function updateConflictDraft(field:string,value:string,base=value){
  if(field==='details'){detailsDraft.value=value;detailsDraftBase=base}
  else if(field==='title'){titleDraft.value=value;titleDraftBase=base}
  else if(field==='blocked_reason'){blockedReasonDraft.value=value;blockedReasonDraftBase=base}
  else if(field==='note'){noteDraft.value=value;noteDraftBase=base}
}
function resolvedConflictPatch(conflict:TicketFieldConflict,value:string):TicketPatch{
  if(conflict.field==='note')return{note_id:conflict.key.slice('note:'.length),note:value};
  if(conflict.field==='tags')return{tags:value.split(',').map(item=>item.trim()).filter(Boolean)};
  if(conflict.field==='up_next')return{up_next:value.toLocaleLowerCase()==='true'};
  if(conflict.field==='blocked_reason')return{blocked_reason:value.trim()||null};
  return{[conflict.field]:value};
}
delegate(document.body,'input','[name="ticket-conflict-resolution"]',(_event,target)=>{fieldConflictResolution.value=(target as HTMLTextAreaElement).value});
delegate(document.body,'click','[data-action="accept-remote-ticket-field"]',()=>{const conflict=fieldConflict.value;if(!conflict)return;updateConflictDraft(conflict.field,conflict.theirs);fieldConflict.value=undefined;fieldConflictResolution.value=''});
delegate(document.body,'click','[data-action="apply-ticket-field-merge"]',()=>{const conflict=fieldConflict.value;if(!conflict)return;const value=fieldConflictResolution.value;if(conflict.field==='title'&&!value.trim()){error.value='Ticket title cannot be empty.';return}updateConflictDraft(conflict.field,value,conflict.theirs);fieldConflict.value=undefined;fieldConflictResolution.value='';void updateSelectedTracked(resolvedConflictPatch(conflict,value))});
